 */
CG3_INLINE bool AABBTree3::isInsidePseudoRandom(const Point3d& p, int numberOfChecks) const
{
    assert(numberOfChecks % 2 == 1);
    int inside = 0, outside = 0;
    double distx = bb.maxX() - bb.minX();
