                break;
            case 2: // z
                n1 = (double)rand()/((double)RAND_MAX/distx) + bb.minX();
                //n1 = distx(e2);
                n2 = (double)rand()/((double)RAND_MAX/disty) + bb.minY();
                //n2 = disty(e2);
                boundingPoint.setX(n1);
