inline Point2<T>::Point2(T x, T y):
    xCoord(x),
    yCoord(y)
{
}

/**
 * @brief Constructor using the values of an EigenVector.
 *
 * @param v
 */
template <class T>
Point2<T>::Point2(const Eigen::VectorXd& v) : xCoord(v(0)), yCoord(v(1)){
}

/**
 * @brief Returns a const reference of the x coordinate.
 * @return a const reference of the x coordinate
 */
template <class T>
inline const T& Point2<T>::x() const
{
    return xCoord;
}

/**
 * @brief Returns a const reference of the y coordinate.
 * @return a const reference of the y coordinate
 */
template <class T>
inline const T& Point2<T>::y() const
{
    return yCoord;
}

/**
 * @brief Calculates and returns the distance between this and otherPoint.
 *
 * @param[in] otherPoint: another point
 * @return the distance between this and otherPoint
 */
template <class T>
inline double Point2<T>::dist(const Point2<T> &otherPoint) const
{
    return std::sqrt ( std::pow((xCoord - otherPoint.xCoord), 2) +
                  std::pow((yCoord - otherPoint.yCoord), 2) );
}

/**
 * @brief Calculates and returns the dot product between this and otherVector.
 * @param[in] otherVector: another vector
 * @return the dot product between this and otherVector
 */
template <class T>
inline double Point2<T>::dot(const Point2<T> &otherVector) const
{
    return xCoord * otherVector.xCoord +
           yCoord * otherVector.yCoord;
}

/**
 * @brief Calculates and returns the perpendicular dot product between this and otherVector.
 * @param[in] otherVector: another vector
 * @return the perpendicular dot product between this and otherVector
 */
template <class T>
inline double Point2<T>::perpendicularDot(const Point2<T>& otherVector) const
{
    return xCoord * otherVector.yCoord -
           yCoord * otherVector.xCoord;
}

/**
 * @brief Point2D<T>::getLength
 * @return the length of this vector.
 */
template <class T>
inline double Point2<T>::length() const
{
    return std::sqrt( xCoord*xCoord + yCoord*yCoord );
}

/**
 * @brief Point2D<T>::getLengthSquared
 * @return the squared length of this vector.
 */
template <class T>
inline double Point2<T>::lengthSquared() const
{
    return xCoord*xCoord + yCoord*yCoord;
}

/**
 * @brief Point2D<T>::min
 * @param[in] otherPoint: another point
 * @return the point composed of the minimum x coordinate and the minimum y coordinate between the two points.
 */
template <class T>
inline Point2<T> Point2<T>::min(const Point2<T> &otherPoint) const
{
    return Point2<T>(std::min(x(), otherPoint.xCoord),
                   std::min(y(), otherPoint.yCoord));
}

/**
 * @brief Point2D<T>::max
